import{i as e,r as t,s as n,t as r}from"./app-qKiKnNug.js";var i=JSON.parse(`{"path":"/org/arc.html","title":"架构","lang":"zh-CN","frontmatter":{"description":"架构 前端、客户端 接入层（Front Door / Ingress） API 网关 / 流量管理层 应用层（业务服务层） 服务治理层（Service Mesh） 数据层（Storage / Cache / MQ） 基础设施层（Infrastructure） 运维监控与安全层（Ops &amp; Security） 1. 接入层（Front Door ...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"架构\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-03-11T05:49:26.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"DeeLMind\\",\\"url\\":\\"https://deelmind.com\\"}]}"],["meta",{"property":"og:url","content":"https://deelmind.com/org/arc.html"}],["meta",{"property":"og:site_name","content":"極客方舟"}],["meta",{"property":"og:title","content":"架构"}],["meta",{"property":"og:description","content":"架构 前端、客户端 接入层（Front Door / Ingress） API 网关 / 流量管理层 应用层（业务服务层） 服务治理层（Service Mesh） 数据层（Storage / Cache / MQ） 基础设施层（Infrastructure） 运维监控与安全层（Ops &amp; Security） 1. 接入层（Front Door ..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-03-11T05:49:26.000Z"}],["meta",{"property":"article:modified_time","content":"2026-03-11T05:49:26.000Z"}]]},"git":{"createdTime":1769836766000,"updatedTime":1773208166000,"contributors":[{"name":"DeeLMind","username":"DeeLMind","email":"deelmind@gmail.com","commits":2,"url":"https://github.com/DeeLMind"}]},"readingTime":{"minutes":2.85,"words":854},"filePathRelative":"org/arc.md","autoDesc":true}`),a={name:`arc.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="架构" tabindex="-1"><a class="header-anchor" href="#架构"><span>架构</span></a></h1><ol start="0"><li>前端、客户端</li><li>接入层（Front Door / Ingress）</li><li>API 网关 / 流量管理层</li><li>应用层（业务服务层）</li><li>服务治理层（Service Mesh）</li><li>数据层（Storage / Cache / MQ）</li><li>基础设施层（Infrastructure）</li><li>运维监控与安全层（Ops &amp; Security）</li></ol><hr><h2 id="_1-接入层-front-door-ingress" tabindex="-1"><a class="header-anchor" href="#_1-接入层-front-door-ingress"><span>1. 接入层（Front Door / Ingress）</span></a></h2><p><strong>职责</strong>：负责所有外部请求入口，提供高可用、高性能访问，同时保证安全。</p><p><strong>功能点</strong>：</p><ul><li>域名解析与负载均衡（DNS）</li><li>静态资源分发（CDN）</li><li>SSL/TLS 终止</li><li>DDoS 防护</li><li>健康检查与访问控制</li></ul><p><strong>关键技术</strong>：</p><table><thead><tr><th>功能</th><th>技术/工具</th></tr></thead><tbody><tr><td>DNS</td><td>Route53, Cloudflare</td></tr><tr><td>CDN</td><td>Akamai, CloudFront, Fastly</td></tr><tr><td>WAF/DDoS</td><td>Cloudflare, AWS WAF</td></tr><tr><td>负载均衡</td><td>Nginx, F5, HAProxy</td></tr></tbody></table><hr><h2 id="_2-api-网关-流量管理层" tabindex="-1"><a class="header-anchor" href="#_2-api-网关-流量管理层"><span>2. API 网关 / 流量管理层</span></a></h2><p><strong>职责</strong>：统一管理微服务接口，控制流量、安全和权限。</p><p><strong>功能点</strong>：</p><ul><li>请求路由与协议转换（HTTP ↔ gRPC）</li><li>认证鉴权（OAuth2 / JWT）</li><li>限流 / 熔断 / 降级</li><li>日志收集和监控指标统计</li><li>A/B 测试与灰度发布</li></ul><p><strong>关键技术</strong>：</p><table><thead><tr><th>功能</th><th>技术/工具</th></tr></thead><tbody><tr><td>API Gateway</td><td>Kong, Apigee, Nginx + Lua</td></tr><tr><td>鉴权</td><td>OAuth2, JWT, Keycloak</td></tr><tr><td>流控熔断</td><td>Resilience4j, Envoy, Istio</td></tr><tr><td>服务网格</td><td>Istio, Linkerd</td></tr></tbody></table><hr><h2 id="_3-应用层-业务服务层" tabindex="-1"><a class="header-anchor" href="#_3-应用层-业务服务层"><span>3. 应用层（业务服务层）</span></a></h2><p><strong>职责</strong>：实现核心业务逻辑和功能，提供可伸缩的微服务。</p><p><strong>架构设计</strong>：</p><ul><li>微服务架构，每个业务模块独立部署</li><li>分层服务：Controller → Service → Repository</li><li>幂等设计，保证重试安全</li><li>异步处理耗时操作（消息队列 / 事件总线）</li></ul><p><strong>关键技术</strong>：</p><table><thead><tr><th>类型</th><th>技术/工具</th></tr></thead><tbody><tr><td>微服务框架</td><td>Spring Boot, NestJS, Go-kit</td></tr><tr><td>RPC / gRPC</td><td>gRPC, Thrift</td></tr><tr><td>异步队列</td><td>Kafka, RabbitMQ, Pulsar</td></tr><tr><td>配置管理</td><td>Nacos, Consul, Spring Cloud Config</td></tr></tbody></table><hr><h2 id="_4-服务治理层-service-mesh" tabindex="-1"><a class="header-anchor" href="#_4-服务治理层-service-mesh"><span>4. 服务治理层（Service Mesh）</span></a></h2><p><strong>职责</strong>：统一管理微服务间调用、服务发现、监控和安全策略。</p><p><strong>功能点</strong>：</p><ul><li>服务注册与发现</li><li>配置中心</li><li>负载均衡（服务级）</li><li>调用链跟踪、熔断、重试</li><li>安全策略（mTLS、访问控制）</li></ul><p><strong>关键技术</strong>：</p><table><thead><tr><th>类型</th><th>技术/工具</th></tr></thead><tbody><tr><td>服务发现</td><td>Consul, Eureka</td></tr><tr><td>服务网格</td><td>Istio, Linkerd</td></tr><tr><td>配置中心</td><td>Nacos, Apollo</td></tr><tr><td>链路追踪</td><td>Jaeger, Zipkin</td></tr></tbody></table><hr><h2 id="_5-数据层-storage-cache-mq" tabindex="-1"><a class="header-anchor" href="#_5-数据层-storage-cache-mq"><span>5. 数据层（Storage / Cache / MQ）</span></a></h2><p><strong>职责</strong>：管理数据存储、缓存、消息队列，提高性能和可用性。</p><p><strong>功能点</strong>：</p><ul><li>关系型数据库存储核心数据</li><li>NoSQL 支撑高并发、高可用存储</li><li>缓存层优化热点数据</li><li>消息队列实现异步处理</li><li>搜索/全文索引</li><li>数据备份与灾备</li></ul><p><strong>关键技术</strong>：</p><table><thead><tr><th>类型</th><th>技术/工具</th></tr></thead><tbody><tr><td>RDBMS</td><td>MySQL, PostgreSQL</td></tr><tr><td>NoSQL</td><td>MongoDB, Cassandra</td></tr><tr><td>缓存</td><td>Redis, Memcached</td></tr><tr><td>消息队列</td><td>Kafka, RabbitMQ, Pulsar</td></tr><tr><td>搜索引擎</td><td>Elasticsearch, Solr</td></tr><tr><td>数据仓库</td><td>ClickHouse, Snowflake</td></tr></tbody></table><hr><h2 id="_6-基础设施层-infrastructure" tabindex="-1"><a class="header-anchor" href="#_6-基础设施层-infrastructure"><span>6. 基础设施层（Infrastructure）</span></a></h2><p><strong>职责</strong>：提供稳定可靠的计算、网络、存储和容器化环境。</p><p><strong>功能点</strong>：</p><ul><li>容器化与编排</li><li>高可用负载均衡</li><li>弹性伸缩和自动扩容</li><li>网络拓扑优化</li><li>灾备与容灾</li></ul><p><strong>关键技术</strong>：</p><table><thead><tr><th>类型</th><th>技术/工具</th></tr></thead><tbody><tr><td>容器</td><td>Docker, Podman</td></tr><tr><td>编排</td><td>Kubernetes, Nomad</td></tr><tr><td>负载均衡</td><td>F5, Nginx, HAProxy</td></tr><tr><td>云基础设施</td><td>AWS, GCP, Azure</td></tr><tr><td>弹性伸缩</td><td>K8s HPA, Cluster Autoscaler</td></tr></tbody></table><hr><h2 id="_7-运维监控与安全层-ops-security" tabindex="-1"><a class="header-anchor" href="#_7-运维监控与安全层-ops-security"><span>7. 运维监控与安全层（Ops &amp; Security）</span></a></h2><p><strong>职责</strong>：保障服务高可用、安全和可观测。</p><p><strong>功能点</strong>：</p><ul><li>日志收集与分析</li><li>性能指标监控</li><li>异常告警与自动化响应</li><li>安全审计、入侵防护</li><li>配置与密钥管理</li></ul><p><strong>关键技术</strong>：</p><table><thead><tr><th>类型</th><th>技术/工具</th></tr></thead><tbody><tr><td>日志收集</td><td>ELK Stack, Loki</td></tr><tr><td>监控告警</td><td>Prometheus + Grafana, Zabbix</td></tr><tr><td>CI/CD</td><td>GitLab CI, ArgoCD, Jenkins</td></tr><tr><td>安全防护</td><td>WAF, IDS/IPS, Vault</td></tr></tbody></table>`,51)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};